import{_ as s,o as n,a as p,b as t}from"./app.DKoEZOcr.js";const c="/ascendc.github.io/pr/5487/assets/lock_unlock.BpeSjq5h.png",l="/ascendc.github.io/pr/5487/assets/setflag_waitflag_vs_lock_unlock_diff.BHszEFGN.png",d=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"同步控制","link":"/api/SIMD-API/basic_api/sync_control/sync_control"},{"text":"核内同步","link":"/api/SIMD-API/basic_api/sync_control/intra_core_sync/intra_core_sync"},{"text":"Mutex（ISASI）","link":"/api/SIMD-API/basic_api/sync_control/intra_core_sync/Mutex_ISASI"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/sync_control/intra_core_sync/Mutex_ISASI.md","filePath":"api/SIMD-API/basic_api/sync_control/intra_core_sync/Mutex_ISASI.md","lastUpdated":1786949923000}'),e={name:"api/SIMD-API/basic_api/sync_control/intra_core_sync/Mutex_ISASI.md"};function i(o,a,_,r,I,g){return n(),p("div",null,[...a[0]||(a[0]=[t('<div><article class="markdown-body"><h1>Mutex(ISASI)<span id="ZH-CN_TOPIC_0000002565915364"></span></h1><p>Mutex用于核内异步流水指令之间的同步控制，其功能类似于传统CPU中的锁机制。通过先锁定再释放指定流水来完成流水间的同步依赖，锁定/解锁指定流水对应Lock/Unlock接口。</p><ul><li><a href="Lock.html">Lock</a>：根据MutexID获取Mutex，若Mutex已被锁定，将阻塞后续指定流水指令队列，直到当前流水的前序指令中对应MutexID的Mutex被<a href="Unlock.html">Unlock</a>。</li><li><a href="Unlock.html">Unlock</a>：直到当前流水的前序指令执行完成后，根据MutexID释放对应Mutex。</li></ul><p><strong>图 1</strong> Lock/UnLock接口<span id="fig58242463299"></span><br><img src="'+c+'" alt title="Lock-UnLock接口"></p><p>每个锁有固定的一个MutexID，在不同编程范式中，该ID的获取以及释放方式不同：</p><ul><li>采用<a href="../../../../../guide/programming_guide/programming_model/ai_core_simd_programming/tpipe_tque_programming/tpipe_tque_paradigm.html">TPipe-TQue框架编程范式</a>时，MutexID需要通过<a href="AllocMutexID_ISASI.html">AllocMutexID</a>/<a href="ReleaseMutexID_ISASI.html">ReleaseMutexID</a>进行申请释放。</li><li>采用<a href="../../../../../guide/programming_guide/programming_model/ai_core_simd_programming/cpp_tensor_programming/static_tensor_programming.html">静态Tensor编程范式</a>时，MutexID由开发者自行管理，建议使用0-27，28-31为系统内部规划预留，不建议使用。</li></ul><p>相对于<a href="SetFlag_WaitFlag_ISASI.html">SetFlag/WaitFlag</a>同步机制，使用Lock/Unlock接口有以下优势：</p><ul><li>内聚性更强，使用时与其它流水线解耦，可以简化反向同步，如图2所示，以PIPE_MTE2与PIPE_V之间同步为例。</li><li>可以使用更多的同步信号量。</li></ul><p><strong>图 2</strong> SetFlag/WaitFlag同步与Lock/Unlock同步代码差异<span id="fig27101823165111"></span><br><img src="'+l+`" alt title="SetFlag-WaitFlag同步与Lock-Unlock同步代码差异"></p><p>Mutex类定义如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">class</span><span class="w"> </span><span class="nc">Mutex</span><span class="w"> </span><span class="p">{</span>
<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">pipe_t</span><span class="w"> </span><span class="n">pipe</span><span class="o">&gt;</span>
<span class="k">static</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Lock</span><span class="p">(</span><span class="n">MutexID</span><span class="w"> </span><span class="n">id</span><span class="p">);</span>
<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">pipe_t</span><span class="w"> </span><span class="n">pipe</span><span class="o">&gt;</span>
<span class="k">static</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Unlock</span><span class="p">(</span><span class="n">MutexID</span><span class="w"> </span><span class="n">id</span><span class="p">);</span>
<span class="p">};</span>
</code></pre></div></article></div>`,1)])])}const m=s(e,[["render",i]]);export{d as __pageData,m as default};
